// FileStatus is the lifecycle state of a file.
type FileStatus int32

// FileStatus values.
const (
	FileStatusUnspecified FileStatus = 0
	FileStatusPending     FileStatus = 1
	FileStatusAvailable   FileStatus = 2
)

func (s FileStatus) String() string {
	switch s {
	case FileStatusPending:
		return "FILE_STATUS_PENDING"
	case FileStatusAvailable:
		return "FILE_STATUS_AVAILABLE"
	}
	return "FILE_STATUS_UNSPECIFIED"
}

// ContentDisposition controls how browsers treat a download.
type ContentDisposition int32

// ContentDisposition values.
const (
	ContentDispositionUnspecified ContentDisposition = 0
	ContentDispositionInline      ContentDisposition = 1
	ContentDispositionAttachment  ContentDisposition = 2
)

func (d ContentDisposition) String() string {
	switch d {
	case ContentDispositionInline:
		return "CONTENT_DISPOSITION_INLINE"
	case ContentDispositionAttachment:
		return "CONTENT_DISPOSITION_ATTACHMENT"
	}
	return "CONTENT_DISPOSITION_UNSPECIFIED"
}

// File is a stored file.
type File struct {
	ID          string            // 1
	Namespace   string            // 2
	Name        string            // 3
	ContentType string            // 4
	Size        int64             // 5
	SHA256      string            // 6
	ETag        string            // 7
	Status      FileStatus        // 8
	Metadata    map[string]string // 9
	CreateTime  time.Time         // 10
	UpdateTime  time.Time         // 11
}

func (m *File) Reset() { *m = File{} }

func (m *File) AppendProto(b []byte) []byte {
	b = pbwire.String(b, 1, m.ID)
	b = pbwire.String(b, 2, m.Namespace)
	b = pbwire.String(b, 3, m.Name)
	b = pbwire.String(b, 4, m.ContentType)
	b = pbwire.Int64(b, 5, m.Size)
	b = pbwire.String(b, 6, m.SHA256)
	b = pbwire.String(b, 7, m.ETag)
	b = pbwire.Int32(b, 8, int32(m.Status))
	b = pbwire.StringMap(b, 9, m.Metadata)
	b = pbwire.Timestamp(b, 10, m.CreateTime)
	b = pbwire.Timestamp(b, 11, m.UpdateTime)
	return b
}

func (m *File) MergeProto(b []byte) error {
	return pbwire.Parse(b, func(f pbwire.Field) error {
		switch f.Num {
		case 1:
			return f.StringTo(&m.ID)
		case 2:
			return f.StringTo(&m.Namespace)
		case 3:
			return f.StringTo(&m.Name)
		case 4:
			return f.StringTo(&m.ContentType)
		case 5:
			return f.Int64To(&m.Size)
		case 6:
			return f.StringTo(&m.SHA256)
		case 7:
			return f.StringTo(&m.ETag)
		case 8:
			return pbwire.EnumTo(f, &m.Status)
		case 9:
			return f.MapEntryTo(&m.Metadata)
		case 10:
			return f.TimeTo(&m.CreateTime)
		case 11:
			return f.TimeTo(&m.UpdateTime)
		}
		return nil
	})
}

