// UploadStreamHeader is the first message of UploadStream.
type UploadStreamHeader struct {
	Name        string            // 1
	ContentType string            // 2
	Size        *int64            // 3 (optional)
	Metadata    map[string]string // 4
}

func (m *UploadStreamHeader) Reset() { *m = UploadStreamHeader{} }

func (m *UploadStreamHeader) AppendProto(b []byte) []byte {
	b = pbwire.String(b, 1, m.Name)
	b = pbwire.String(b, 2, m.ContentType)
	if m.Size != nil {
		b = pbwire.Int64Always(b, 3, *m.Size)
	}
	b = pbwire.StringMap(b, 4, m.Metadata)
	return b
}

func (m *UploadStreamHeader) MergeProto(b []byte) error {
	return pbwire.Parse(b, func(f pbwire.Field) error {
		switch f.Num {
		case 1:
			return f.StringTo(&m.Name)
		case 2:
			return f.StringTo(&m.ContentType)
		case 3:
			return f.OptionalInt64To(&m.Size)
		case 4:
			return f.MapEntryTo(&m.Metadata)
		}
		return nil
	})
}

// UploadStreamRequest carries either the header (first message) or a chunk.
type UploadStreamRequest struct {
	// oneof payload
	Header *UploadStreamHeader // 1
	Chunk  []byte              // 2
}

func (m *UploadStreamRequest) Reset() { *m = UploadStreamRequest{} }

func (m *UploadStreamRequest) AppendProto(b []byte) []byte {
	switch {
	case m.Header != nil:
		b = pbwire.MessageField(b, 1, m.Header)
	case m.Chunk != nil:
		b = pbwire.BytesAlways(b, 2, m.Chunk)
	}
	return b
}

func (m *UploadStreamRequest) MergeProto(b []byte) error {
	return pbwire.Parse(b, func(f pbwire.Field) error {
		switch f.Num {
		case 1:
			if f.Type != pbwire.Bytes {
				return nil
			}
			m.Chunk = nil
			return pbwire.MessageTo(f, &m.Header)
		case 2:
			if f.Type != pbwire.Bytes {
				return nil
			}
			m.Header = nil
			return f.BytesTo(&m.Chunk)
		}
		return nil
	})
}

